head.script:
// 화면 표시(Cell 텍스트)와 getCellDisplayData 반환값 비교 출력
scwin.btn_check_onclick = function (e) {
    let colList = ["dateA", "dateB"];
    for (let i = 0; i < colList.length; i++) {
        let td = document.getElementById(grd_target.id + "_cell_0_" + i);
        let display = td ? td.textContent : "";
        let ret = grd_target.getCellDisplayData(0, colList[i]);
        scwin.setReturnValue("[" + colList[i] + "] 기대 : '" + display + "'  /  실제 : '" + ret + "'  → " + (display === ret ? "PASS" : "FAIL"));
    }
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
